"""Dependency-free presentation for the read-only research dashboard."""

DASHBOARD_HTML = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>NFL Prop Research</title>
<style>
:root{color-scheme:dark;--bg:#080b0d;--panel:#101519;--raised:#151b20;--line:#273038;--text:#f2f5f4;--muted:#8e9ba4;--green:#36d17c;--amber:#f1b84b;--red:#ff6670;--blue:#67a9ff}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:13px/1.45 Inter,ui-sans-serif,system-ui,-apple-system,sans-serif}button,input,select{font:inherit}.shell{max-width:1600px;margin:auto;padding:20px 24px 42px}.topbar{display:flex;align-items:center;gap:12px;padding:3px 0 18px;border-bottom:1px solid var(--line)}h1{font-size:21px;letter-spacing:-.02em;margin:0}.badge,.status,.pill{border:1px solid var(--line);border-radius:999px;padding:3px 8px;font-size:11px;font-weight:700}.badge{background:#1a2126;color:#cbd3d8}.status{color:var(--green)}.status:before{content:'';display:inline-block;width:7px;height:7px;border-radius:50%;background:currentColor;margin-right:6px}.topmeta{margin-left:auto;display:flex;gap:22px;color:var(--muted);font-size:11px}.topmeta b{display:block;color:var(--text);font-size:12px;margin-top:2px}.kpis{display:grid;grid-template-columns:repeat(6,minmax(120px,1fr));gap:10px;margin:16px 0}.card{background:var(--panel);border:1px solid var(--line);border-radius:9px}.kpi{padding:13px 14px}.kpi span{color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:.06em}.kpi strong{display:block;font-size:20px;margin-top:4px}.section{margin-top:12px}.section-head{display:flex;align-items:flex-end;justify-content:space-between;padding:16px 17px 12px}.section-head h2{font-size:15px;margin:0}.section-head p{color:var(--muted);margin:3px 0 0;font-size:11px}.filters{display:flex;gap:7px;flex-wrap:wrap;padding:0 17px 13px}.filters input,.filters select{color:var(--text);background:#0b1013;border:1px solid var(--line);border-radius:6px;padding:7px 9px;outline:none;min-width:125px}.filters input{min-width:190px}.filters input:focus,.filters select:focus{border-color:#52718a}.table-wrap{overflow:auto;max-height:590px;border-top:1px solid var(--line)}table{border-collapse:collapse;width:100%;white-space:nowrap}th{position:sticky;top:0;z-index:1;background:#11171b;color:var(--muted);font-size:10px;text-transform:uppercase;letter-spacing:.06em;text-align:left;padding:9px 10px;border-bottom:1px solid var(--line);cursor:pointer}td{padding:10px;border-bottom:1px solid #20282e;color:#cbd3d8}tbody tr{cursor:pointer}tbody tr:hover{background:#151d22}.primary{font-weight:700;color:var(--text)}.sub{display:block;color:var(--muted);font-size:11px}.edge{font-weight:800;color:var(--green)}.edge.mid{color:var(--amber)}.edge.low{color:var(--muted)}.pill{display:inline-block;padding:2px 7px;color:#bec8ce}.pill.good{color:var(--green);border-color:#24583b}.pill.warn{color:var(--amber);border-color:#5b4826}.empty{text-align:center;padding:56px 20px;color:var(--muted)}.empty strong{display:block;color:var(--text);font-size:15px;margin-bottom:5px}.lower{display:grid;grid-template-columns:1fr 1fr;gap:12px}.content{padding:0 17px 16px}.metric-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.mini{background:var(--raised);border:1px solid var(--line);border-radius:7px;padding:10px}.mini span{display:block;color:var(--muted);font-size:10px;text-transform:uppercase}.mini b{font-size:16px}.note{color:var(--muted);padding:20px 0}.diagnostics summary{padding:15px 17px;cursor:pointer;font-weight:700}.diagnostics .content{border-top:1px solid var(--line);padding-top:12px}.drawer-backdrop{position:fixed;inset:0;background:#000a;z-index:10;opacity:0;pointer-events:none;transition:.18s}.drawer-backdrop.open{opacity:1;pointer-events:auto}.drawer{position:fixed;right:0;top:0;bottom:0;width:min(660px,95vw);background:#0d1215;border-left:1px solid var(--line);z-index:11;transform:translateX(100%);transition:.22s;overflow:auto;padding:22px}.drawer.open{transform:none}.copy-field{display:flex;gap:6px;margin-top:10px}.copy-field input{min-width:0;flex:1;color:var(--text);background:#080b0d;border:1px solid var(--line);border-radius:6px;padding:7px 9px;font-family:ui-monospace,monospace}.copy-field button{color:var(--text);background:var(--raised);border:1px solid var(--line);border-radius:6px;padding:7px 10px;cursor:pointer}.close{float:right;background:transparent;border:1px solid var(--line);color:var(--text);border-radius:6px;padding:5px 9px;cursor:pointer}.drawer h2{margin:0 0 3px;font-size:20px}.drawer h3{font-size:12px;text-transform:uppercase;letter-spacing:.08em;color:var(--muted);margin:22px 0 8px}.detail-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:var(--line);border:1px solid var(--line);border-radius:7px;overflow:hidden}.detail-grid div{padding:10px;background:var(--panel);min-width:0}.detail-grid span{color:var(--muted);display:block;font-size:10px;text-transform:uppercase}.detail-grid b{word-break:break-word}.disclaimer{color:var(--muted);font-size:11px;margin:10px 0 0}.error{color:var(--red)}
@media(max-width:1000px){.kpis{grid-template-columns:repeat(3,1fr)}.lower{grid-template-columns:1fr}.topmeta{display:none}}@media(max-width:620px){.shell{padding:14px 10px}.topbar{flex-wrap:wrap}.kpis{grid-template-columns:repeat(2,1fr)}.section-head{align-items:flex-start;flex-direction:column}.detail-grid{grid-template-columns:repeat(2,1fr)}}
</style></head><body><main class="shell">
<header class="topbar"><h1>NFL Prop Research</h1><span class="badge">Production</span><span class="status" id="health">Loading</span><div class="topmeta"><span>Latest scheduler<b id="latest-run">—</b></span><span>Feature freshness<b id="feature-fresh">—</b></span><span>Quota state<b id="quota-top">—</b></span></div></header>
<section class="kpis" aria-label="Research summary"><div class="card kpi"><span>Total observations</span><strong id="k-total">0</strong></div><div class="card kpi"><span>Observations today</span><strong id="k-today">0</strong></div><div class="card kpi"><span>Matchups represented</span><strong id="k-games">0</strong></div><div class="card kpi"><span>Settled / Unsettled</span><strong id="k-settlement">0 / 0</strong></div><div class="card kpi"><span>Quota remaining</span><strong id="k-quota">—</strong></div><div class="card kpi"><span>Model versions</span><strong id="k-models">0</strong></div></section>
<section class="card section"><div class="section-head"><div><h2>Player Prop Opportunities</h2><p>Descriptive model and market observations · newest captures first</p></div><span class="pill">Read only</span></div><div class="filters"><input id="search" placeholder="Search player or team" aria-label="Search player or team"><select id="market"><option value="">All markets</option></select><select id="side"><option value="">All sides</option><option>over</option><option>under</option><option>yes</option><option>no</option></select><select id="window"><option value="">All windows</option></select><select id="tier"><option value="">All edge tiers</option></select><select id="settled"><option value="">All statuses</option><option value="settled">Settled</option><option value="unsettled">Unsettled</option></select><select id="quality"><option value="">All evidence quality</option></select><select id="weather"><option value="">Any weather</option><option value="concern">Weather concern</option></select><select id="injury"><option value="">Any injury status</option><option value="concern">Injury concern</option></select><select id="role"><option value="">Any role status</option><option value="uncertain">Role uncertainty</option></select></div><div class="table-wrap"><table><thead><tr><th data-key="player">Player</th><th data-key="matchup">Matchup</th><th data-key="market">Prop</th><th data-key="side">Side</th><th data-key="line">HR line</th><th data-key="price">HR price</th><th data-key="point">Model point</th><th data-key="prob">Model prob.</th><th data-key="breakeven">Break-even</th><th data-key="edge">Model edge</th><th data-key="tier">Edge tier</th><th data-key="window">Window</th><th data-key="time">Captured</th><th data-key="coverage">References</th><th>Confirmation</th><th data-key="quality">Context</th></tr></thead><tbody id="rows"></tbody></table><div class="empty" id="empty"><strong>Waiting for first scheduled capture</strong>Observations will appear here after the scheduler records a capture.</div></div></section>
<div class="lower"><section class="card section"><div class="section-head"><div><h2>Strategy Performance</h2><p>Prospective selections recorded in the append-only selection journal only</p></div></div><div class="content" id="performance"><div class="note"><strong>Awaiting prospective selections.</strong> No strategy performance is available until selected observations settle.</div></div></section><section class="card section"><div class="section-head"><div><h2>Model Evaluation</h2><p>Calibration over raw settled side observations · not a betting record</p></div></div><div class="content" id="model-evaluation"><div class="note">Model calibration will appear after observations settle.</div></div></section><details class="card section diagnostics"><summary>Scheduler &amp; operational diagnostics</summary><div class="content" id="diagnostics"><div class="note">No scheduler executions recorded.</div></div></details></div>
<p class="disclaimer">Research context only, not betting recommendations. This interface contains no wagering, ordering, or recommendation actions.</p></main>
<div class="drawer-backdrop" id="backdrop"></div><aside class="drawer" id="drawer" aria-hidden="true"><button class="close" id="close">Close</button><div id="detail"></div></aside>
<script>
const $=s=>document.querySelector(s), marketNames={player_pass_yds:'Passing Yards',player_reception_yds:'Receiving Yards',player_receptions:'Receptions'};let all=[],sort={key:'time',asc:false};
const pct=v=>v==null?'—':(Number(v)*100).toFixed(1)+'%', edge=v=>v==null?'—':(v>=0?'+':'')+Number(v).toFixed(2)+' pp', odds=v=>v==null?'—':(v>0?'+':'')+v, num=v=>v==null?'—':Number(v).toFixed(1), dt=v=>v?new Date(v).toLocaleString('en-US',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',timeZone:'UTC'})+' UTC':'—', full=v=>v?new Date(v).toISOString().replace('.000',''):'—', esc=v=>String(v??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function label(s){return marketNames[s]||String(s||'—').replaceAll('_',' ')}function flag(o){let f=o.confirmation_flags||{};if(f.both_disagree||f.cross_market_conflict)return '<span class="pill warn">Cross-Market Conflict</span>';if(f.both_agree||f.reference_confirmed)return '<span class="pill good">Reference Confirmed</span>';if(!o.reference_book_coverage)return '<span class="pill warn">Insufficient Coverage</span>';return '<span class="pill">Available</span>'}
function populate(id,values,render=label){let el=$(id),current=el.value;[...new Set(values.filter(Boolean))].sort().forEach(v=>{let op=document.createElement('option');op.value=v;op.textContent=render(v);el.append(op)});el.value=current}
function render(){let q=$('#search').value.trim().toLowerCase(), rows=all.filter(o=>(!q||[o.player.name,o.event.team,o.event.opponent].some(v=>String(v||'').toLowerCase().includes(q)))&&(!$('#market').value||o.canonical_market===$('#market').value)&&(!$('#side').value||o.side===$('#side').value)&&(!$('#window').value||o.capture_window===$('#window').value)&&(!$('#tier').value||o.edge_tier===$('#tier').value)&&(!$('#settled').value||o.settlement_status===$('#settled').value)&&(!$('#quality').value||o.context_overlay?.evidence_quality===$('#quality').value)&&(!$('#weather').value||o.context_overlay?.dimensions?.weather_context?.label==='concern')&&(!$('#injury').value||o.context_overlay?.dimensions?.injury_context?.label==='concern')&&(!$('#role').value||o.context_overlay?.flags?.role_uncertainty));let value=(o,k)=>({player:o.player.name,matchup:o.event.matchup,market:o.canonical_market,side:o.side,line:o.hard_rock_line,price:o.hard_rock_american_price,point:o.model_point_prediction,prob:o.model_probability,breakeven:o.offered_price_break_even_probability,edge:o.probability_edge_pp,tier:o.edge_tier,window:o.capture_window,time:o.captured_at_utc,coverage:o.reference_book_coverage,quality:o.context_overlay?.evidence_quality}[k]??'');rows.sort((a,b)=>{let x=value(a,sort.key),y=value(b,sort.key);return (typeof x==='number'?x-y:String(x).localeCompare(String(y)))*(sort.asc?1:-1)});$('#rows').innerHTML=rows.map(o=>`<tr data-id="${esc(o.observation_id)}"><td><span class="primary">${esc(o.player.name)}</span><span class="sub">${esc(o.event.team)}</span></td><td>${esc(o.event.matchup)}</td><td>${esc(label(o.canonical_market))}</td><td class="primary">${esc(o.side).toUpperCase()}</td><td>${num(o.hard_rock_line)}</td><td>${odds(o.hard_rock_american_price)}</td><td>${num(o.model_point_prediction)}</td><td>${pct(o.model_probability)}</td><td>${pct(o.offered_price_break_even_probability)}</td><td class="edge ${Math.abs(o.probability_edge_pp)<2?'low':Math.abs(o.probability_edge_pp)<5?'mid':''}">${edge(o.probability_edge_pp)}</td><td>${esc(o.edge_tier)}</td><td>${esc(o.capture_window)}</td><td>${dt(o.captured_at_utc)}</td><td>${o.reference_book_coverage??0} books</td><td>${flag(o)}</td><td><span class="pill ${o.context_overlay?.evidence_quality==='strong'?'good':o.context_overlay?.evidence_quality==='weak'?'warn':''}" title="${esc(o.context_overlay?.evidence_quality_reason)}">${esc(o.context_overlay?.evidence_quality||'insufficient_context')}</span></td></tr>`).join('');$('#empty').style.display=rows.length?'none':'block';document.querySelectorAll('#rows tr').forEach(tr=>tr.onclick=()=>openDetail(tr.dataset.id))}
function metric(label,value){return `<div class="mini"><span>${esc(label)}</span><b>${esc(value)}</b></div>`}function copyField(value){return `<label class="copy-field"><input readonly aria-label="Observation ID" value="${esc(value)}"><button type="button">Copy ID</button></label>`}function detailCell(label,value){return `<div><span>${esc(label)}</span><b>${esc(value)}</b></div>`}function failures(items){if(!items?.length)return '';return `<tr><td colspan="8"><details><summary class="error">${items.length} failed capture slot${items.length===1?'':'s'} — show details</summary><div class="table-wrap"><table><thead><tr><th>Event / matchup</th><th>Window / kickoff</th><th>Category</th><th>Sanitized reason</th><th>Provider request</th><th>Credits est. / actual</th><th>Retryable</th></tr></thead><tbody>${items.map(f=>`<tr><td><span class="primary">${esc(f.provider_event_id||f.event_id)}</span><span class="sub">${esc(f.matchup)}</span></td><td>${esc(f.slot)}<span class="sub">${full(f.kickoff_utc)}</span></td><td>${esc(f.failure_category||'unknown_capture_failure')}</td><td class="error">${esc(f.reason)}</td><td>${f.provider_request_made===true?'Yes':f.provider_request_made===false?'No':'—'}</td><td>${esc(f.estimated_credit_cost??'—')} / ${esc(f.actual_credit_cost??'—')}</td><td>${f.retryable===true?'Yes':f.retryable===false?'No':'—'}</td></tr>`).join('')}</tbody></table></div></details></td></tr>`}
async function openDetail(id){$('#drawer').classList.add('open');$('#backdrop').classList.add('open');$('#drawer').setAttribute('aria-hidden','false');$('#detail').innerHTML='<div class="note">Loading observation…</div>';try{let [o,t]=await Promise.all([fetch('/research/observations/'+encodeURIComponent(id)).then(r=>r.json()),fetch('/research/observations/'+encodeURIComponent(id)+'/timeline').then(r=>r.json())]);let u=o.provenance?.uncertainty||{},refs=o.provenance?.reference_context?.books||[];$('#detail').innerHTML=`<h2>${esc(o.player.name)}</h2><span class="sub">${esc(o.event.matchup)} · ${esc(label(o.canonical_market))}</span>${copyField(o.observation_id)}<h3>Observation</h3><div class="detail-grid">${detailCell('Kickoff',full(o.kickoff_utc))}${detailCell('Side',o.side.toUpperCase())}${detailCell('Capture window',o.capture_window)}${detailCell('Hard Rock line',num(o.hard_rock_line))}${detailCell('Hard Rock price',odds(o.hard_rock_american_price))}${detailCell('Break-even',pct(o.offered_price_break_even_probability))}${detailCell('Model point',num(o.model_point_prediction))}${detailCell('Model Over',pct(o.model_over_probability))}${detailCell('Model Under',pct(o.model_under_probability))}${detailCell('Probability edge',edge(o.probability_edge_pp))}${detailCell('Model artifact',o.model_version)}${detailCell('Residual bucket',u.residual_bucket)}${detailCell('Uncertainty',u.method+' / '+u.version)}${detailCell('Feature built',full(o.feature_built_at_utc))}${detailCell('Feature freshness',o.feature_freshness.age_seconds==null?'—':o.feature_freshness.age_seconds+'s'+(o.feature_freshness.stale?' · stale':''))}${detailCell('Provider updated',full(o.provider_freshness.updated_at_utc||o.provider_freshness.observed_at_utc))}${detailCell('Provider freshness',o.provider_freshness.age_seconds==null?'—':o.provider_freshness.age_seconds+'s'+(o.provider_freshness.stale?' · stale':''))}</div><h3>Pregame context overlay</h3>${contextDetail(o.context_overlay)}<p class="disclaimer">Separate from the production model. No probability, edge, or point prediction is adjusted.</p><h3>Reference &amp; Kalshi context</h3><div class="detail-grid">${detailCell('Reference books',refs.length?refs.join(', '):o.reference_book_coverage+' represented')}${detailCell('Median line',num(o.reference_median_line))}${detailCell('Same-threshold prob.',pct(o.same_threshold_reference_probability))}${detailCell('Kalshi bid',pct(o.kalshi.yes_bid))}${detailCell('Kalshi ask',pct(o.kalshi.yes_ask))}${detailCell('Midpoint (non-executable)',pct(o.kalshi.midpoint))}${detailCell('Spread',pct(o.kalshi.spread))}${detailCell('Volume',o.kalshi.volume)}${detailCell('Open interest',o.kalshi.open_interest)}</div><h3>Confirmation</h3><p>${flag(o)}</p><h3>Capture timeline</h3>${timeline(t.items)}${o.settlement?`<h3>Settlement</h3><div class="detail-grid">${detailCell('Settled at',full(o.settlement.settled_at_utc))}${detailCell('Actual value',o.settlement.actual_value)}${detailCell('Result',o.settlement.result)}${detailCell('Paper P&L',o.settlement.paper_profit_loss)}</div>`:''}`;let copy=$('#detail .copy-field button'),input=$('#detail .copy-field input');copy.onclick=async()=>{input.select();await navigator.clipboard.writeText(input.value);copy.textContent='Copied'} }catch(e){$('#detail').innerHTML='<p class="error">Observation detail could not be loaded.</p>'}}
function contextDetail(c){if(!c?.available)return '<div class="note">No external context snapshot was available.</div>';let d=c.dimensions||{}, cells=[['Evidence quality',c.evidence_quality],['Known as of',full(c.as_of_utc)],['Weather',d.weather_context?.label+' — '+d.weather_context?.reason],['Injury',d.injury_context?.label+' — '+d.injury_context?.reason],['Role',d.role_context?.label+' — '+d.role_context?.reason],['Freshness',d.data_freshness?.label+' — '+d.data_freshness?.reason]];let flags=Object.entries(c.flags||{}).filter(x=>x[1]).map(x=>x[0]).join(', ')||'None';return '<div class="detail-grid">'+cells.map(x=>detailCell(x[0],x[1])).join('')+detailCell('Flags',flags)+'</div>'}function timeline(items){if(!items||items.length<2)return '<div class="note">More than one capture is needed to show market movement.</div>';return `<div class="table-wrap"><table><thead><tr><th>Window</th><th>Line</th><th>HR price</th><th>Model prob.</th><th>Edge</th><th>Captured UTC</th></tr></thead><tbody>${items.map(x=>`<tr><td>${esc(x.capture_window)}</td><td>${num(x.hard_rock_line)}</td><td>${odds(x.hard_rock_american_price)}</td><td>${pct(x.model_probability)}</td><td class="edge">${edge(x.probability_edge_pp)}</td><td>${full(x.captured_at_utc)}</td></tr>`).join('')}</tbody></table></div>`}
function close(){ $('#drawer').classList.remove('open');$('#backdrop').classList.remove('open');$('#drawer').setAttribute('aria-hidden','true')}$('#close').onclick=close;$('#backdrop').onclick=close;document.addEventListener('keydown',e=>{if(e.key==='Escape')close()});
async function init(){try{let [s,o,e]=await Promise.all([fetch('/research/summary').then(r=>r.json()),fetch('/research/observations?limit=200').then(r=>r.json()),fetch('/research/executions?limit=10').then(r=>r.json())]);all=o.items;$('#k-total').textContent=s.total_observations;$('#k-today').textContent=s.observations_today;$('#k-games').textContent=s.represented_matchups;$('#k-settlement').textContent=s.settlement_counts.settled+' / '+s.settlement_counts.unsettled;$('#k-quota').textContent=s.latest_quota_state?.after??'—';$('#k-models').textContent=s.current_model_versions_observed.length;$('#latest-run').textContent=dt(s.latest_scheduler_execution_timestamp);$('#feature-fresh').textContent=dt(s.latest_feature_build_timestamp);$('#quota-top').textContent=s.latest_quota_state?s.latest_quota_state.before+' → '+s.latest_quota_state.after:'Not reported';let unhealthy=e.items[0]?.failed_count>0;$('#health').textContent=unhealthy?'Attention':(e.items.length?'Healthy':'Awaiting data');$('#health').style.color=unhealthy?'var(--amber)':'var(--green)';populate('#market',all.map(x=>x.canonical_market));populate('#window',all.map(x=>x.capture_window),x=>x);populate('#tier',all.map(x=>x.edge_tier),x=>x);populate('#quality',all.map(x=>x.context_overlay?.evidence_quality),x=>x);render();let p=s.strategy_performance;if(p.available){$('#performance').innerHTML=`<div class="metric-grid">${metric('Selected / settled',p.selected_count+' / '+p.settled_count)}${metric('W / L / P',p.wins+' / '+p.losses+' / '+p.pushes)}${metric('Paper P&L',p.paper_profit_loss.toFixed(2))}${metric('Realized ROI',pct(p.realized_roi))}</div><h3>Selected results by market</h3>${breakdown(p.by_market)}<h3>Selected results by edge tier</h3>${breakdown(p.by_edge_tier)}<h3>Selected results by capture window</h3>${breakdown(p.by_capture_window)}`}else{$('#performance').innerHTML=`<div class="note"><strong>${esc(p.note)}</strong><br>ROI and paper P&amp;L are unavailable; raw OVER/UNDER settlements are not substituted.</div>`}let m=s.model_evaluation;if(m){$('#model-evaluation').innerHTML=`<div class="metric-grid">${metric('Settled observations',m.settled_observation_count)}${metric('Brier observations',m.brier_observation_count)}${metric('Brier score',m.brier_score==null?'—':m.brier_score.toFixed(4))}</div><p class="disclaimer">${esc(m.note)}</p>`}if(e.items.length)$('#diagnostics').innerHTML='<div class="table-wrap"><table><thead><tr><th>Started</th><th>Due</th><th>Selected</th><th>Completed</th><th>Failed</th><th>Deferred</th><th>Quota</th><th>Errors</th></tr></thead><tbody>'+e.items.map(x=>`<tr><td>${dt(x.started_at_utc)}</td><td>${x.due_count}</td><td>${x.selected_count}</td><td>${x.completed_count}</td><td>${x.failed_count}</td><td>${x.deferred_count}</td><td>${x.quota_before??'—'} → ${x.quota_after??'—'}</td><td>${esc((x.errors||[]).map(v=>v.message||v).join('; ')||'None')}</td></tr>${failures(x.failed_slots)}`).join('')+'</tbody></table></div>'}catch(e){$('#health').textContent='Unavailable';$('#health').style.color='var(--red)';$('#empty').innerHTML='<strong>Research data unavailable</strong>The read-only repository could not be reached.'}}
function breakdown(obj){let entries=Object.entries(obj||{});if(!entries.length)return '<div class="note">No grouped results.</div>';return '<div class="table-wrap"><table><thead><tr><th>Group</th><th>Count</th><th>W / L / P</th><th>Paper P&L</th></tr></thead><tbody>'+entries.map(([k,v])=>`<tr><td>${esc(label(k))}</td><td>${v.count}</td><td>${v.wins} / ${v.losses} / ${v.pushes}</td><td>${Number(v.paper_profit_loss).toFixed(2)}</td></tr>`).join('')+'</tbody></table></div>'}
document.querySelectorAll('.filters input,.filters select').forEach(x=>x.addEventListener('input',render));document.querySelectorAll('th[data-key]').forEach(x=>x.onclick=()=>{sort={key:x.dataset.key,asc:sort.key===x.dataset.key?!sort.asc:true};render()});init();
</script></body></html>'''
